async function accessIdentity(req,aud){
 const token=req.headers.get('Cf-Access-Jwt-Assertion');
 if(!token||!aud)return null;
 try{
  const parts=token.split('.');if(parts.length!==3)return null;
  const dec=x=>Uint8Array.from(atob(x.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-x.length%4)%4)),c=>c.charCodeAt(0));
  const header=JSON.parse(new TextDecoder().decode(dec(parts[0])));
  const payload=JSON.parse(new TextDecoder().decode(dec(parts[1])));
  const now=Math.floor(Date.now()/1000);
  if(header.alg!=='RS256'||typeof header.kid!=='string'||payload.iss!=='https://gsystem-pages.cloudflareaccess.com'||!Array.isArray(payload.aud)||!payload.aud.includes(aud)||typeof payload.exp!=='number'||payload.exp<=now||typeof payload.nbf!=='number'||payload.nbf>now)return null;
  const certResponse=await fetch('https://gsystem-pages.cloudflareaccess.com/cdn-cgi/access/certs');
  if(!certResponse.ok)return null;
  const certs=await certResponse.json();const key=certs.keys?.find(k=>k.kid===header.kid&&k.kty==='RSA'&&k.alg==='RS256')||certs.keys?.find(k=>k.kid===header.kid&&k.kty==='RSA');
  if(!key)return null;
  const verificationKey=await crypto.subtle.importKey('jwk',key,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']);
  const valid=await crypto.subtle.verify('RSASSA-PKCS1-v1_5',verificationKey,dec(parts[2]),new TextEncoder().encode(parts[0]+'.'+parts[1]));
  return valid?payload:null;
 }catch{return null}
}
