async function servePhoto(name,req,ctx){
 const entry=photos[name];if(!entry)return error('Not found.',404);
 const cache=caches.default;
 const key=new Request(new URL('/media/'+name,req.url).toString());
 const hit=await cache.match(key);if(hit)return hit;
 const [id,width]=entry;
 try{
  const src='https://images.pexels.com/photos/'+id+'/pexels-photo-'+id+'.jpeg?auto=compress&cs=tinysrgb&w='+width;
  const remote=await fetch(src,{cf:{cacheTtl:604800,cacheEverything:true}});
  if(remote.ok&&(remote.headers.get('content-type')||'').startsWith('image/')){
    const result=new Response(remote.body,{headers:{'content-type':remote.headers.get('content-type')||'image/jpeg','cache-control':'public,max-age=604800,immutable','x-content-type-options':'nosniff','cross-origin-resource-policy':'same-origin'}});
    ctx?.waitUntil(cache.put(key,result.clone()));
    return result;
  }
 }catch(err){console.log('photo fallback',name,String(err))}
 return new Response(fallbackImage(name),{headers:{'content-type':'image/svg+xml','cache-control':'public,max-age=1800','x-content-type-options':'nosniff'}});
}
